   el token más claro disponible (F-003). Ningún hex, ningún rgb(), nunca. */

.page {
  min-width: 0;
  display: flex;
  flex-direction: column;
}

.eyebrow {
  font-family: var(--bw-font-title);
  font-size: 10px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--bw-steel-mist);
  margin-bottom: 4px;
}

.title {
  font-family: var(--bw-font-title);
  font-size: 20px;
  font-weight: 700;
  color: var(--bw-deep-steel);
  margin-bottom: 3px;
}

.subtitle {
  font-size: 14px;
  color: var(--bw-steel-mist);
  line-height: 1.6;
  margin-bottom: 16px;
  max-width: 560px;
}

.e2eeBar {
  display: flex;
  align-items: center;
  gap: 8px;
  font-family: var(--bw-font-mono);
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--bw-signal-green);
  margin-bottom: 14px;
  padding: 6px 10px;
  background: var(--bw-badge-success-bg);
  border: 1px solid var(--bw-badge-success-border);
  border-radius: 5px;
  width: fit-content;
}

.e2eeIcon {
  font-size: 12px;
}

.actionsBar {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 14px;
}

.searchWrap {
  position: relative;
  flex: 1;
  max-width: 300px;
}

.searchIcon {
  position: absolute;
  left: 10px;
  top: 50%;
  transform: translateY(-50%);
  color: var(--bw-input-placeholder);
  font-size: 15px;
  pointer-events: none;
}

.searchInput {
  width: 100%;
  height: 36px;
  padding: 0 10px 0 32px;
  border: 1px solid var(--bw-line-steel-strong);
  border-radius: 5px;
  font-size: 13px;
  color: var(--bw-deep-steel);
  outline: none;
  font-family: inherit;
  background: var(--bw-warm-cream);
  transition: border-color 0.15s;
}

.searchInput:focus {
  border-color: var(--bw-calibration-blue);
}

.searchInput::placeholder {
  color: var(--bw-input-placeholder);
}

.contactGroup {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 2px;
}

.primaryBtn {
  height: 36px;
  padding: 0 18px;
  background: var(--bw-calibration-blue);
  border: none;
  border-radius: 5px;
  color: var(--bw-warm-cream);
  font-size: 13px;
  font-weight: 500;
  cursor: not-allowed;
  font-family: inherit;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  white-space: nowrap;
  opacity: 0.55;
}

.btnIcon {
  font-size: 15px;
}

.outOfScope {
  font-size: 11px;
  color: var(--bw-hint-steel);
  line-height: 1.2;
  padding-left: 2px;
}

.threadCount {
  font-size: 12px;
  color: var(--bw-input-placeholder);
  margin-left: auto;
  white-space: nowrap;
}

.errorBanner {
  margin-top: 14px;
  padding: 12px 14px;
  border-radius: 6px;
  background: var(--bw-sensitive-bg);
  border: 1px solid var(--bw-badge-danger-border);
  color: var(--bw-error-text);
  font-size: 13px;
  line-height: 1.5;
  display: flex;
  gap: 8px;
  align-items: flex-start;
}

.errorIcon {
  font-size: 15px;
  margin-top: 1px;
  flex-shrink: 0;
}

.statusBox {
  padding: 32px;
  text-align: center;
  font-size: 13px;
  color: var(--bw-steel-mist);
}

.pagination {
  display: flex;
  align-items: center;
  gap: 4px;
  margin-top: 14px;
}

.pageBtn {
  min-width: 30px;
  height: 30px;
  padding: 0 8px;
  border: 1px solid var(--bw-line-steel-strong);
  border-radius: 4px;
  background: var(--bw-warm-cream);
  font-size: 12px;
  color: var(--bw-ink-steel);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: inherit;
  transition: border-color 0.12s, color 0.12s;
}

.pageBtn:hover:not(:disabled) {
  border-color: var(--bw-brass);
  color: var(--bw-brass);
}

.pageBtn:disabled {
  color: var(--bw-hint-steel);
  cursor: default;
  opacity: 0.6;
}

.pageActive,
.pageActive:hover:not(:disabled) {
  background: var(--bw-deep-steel);
  border-color: var(--bw-deep-steel);
  color: var(--bw-warm-cream);
  cursor: default;
}

