import { useEffect, useState } from 'react';
import {
  fetchThreadPage,
  pageCount,
  PAGE_SIZE,
  type ThreadPage,
} from '../../lib/threads';
import type { MemberProfile } from '../../lib/session';
import { ThreadList } from './ThreadList';
import styles from './Messages.module.css';

/**
 * MSG-01 · Lista de Hilos — pantalla.
 *
 * Posee la búsqueda y la paginación; ThreadList es solo presentacional.
 * `now` es inyectable para que los tests no dependan del reloj.
 */
export interface MessagesProps {
  profile: MemberProfile;
  now?: Date | undefined;
  onOpenThread?: (threadId: string) => void;
}

/**
 * El error de PostgREST no siempre es un `Error`: rechaza con un objeto plano
 * { code, message }. `String(e)` daría `[object Object]`; hay que sacar `code`
 * y/o `message` cuando existan y pintarlos junto a la frase para humanos (F-128).
 */
function formatError(e: unknown): string {
  if (e instanceof Error) return e.message;
  if (typeof e === 'object' && e !== null) {
    const record = e as { code?: unknown; message?: unknown };
    const bits: string[] = [];
    if (typeof record.code === 'string' && record.code.trim() !== '') bits.push(record.code);
    if (typeof record.message === 'string' && record.message.trim() !== '') bits.push(record.message);
    if (bits.length > 0) return bits.join(' · ');
  }
  return String(e);
}

export function Messages({ profile, now = new Date(), onOpenThread }: MessagesProps) {
  // F-118: MSG-02 no existía cuando se escribió esta tarea; el shell pasa la prop
  // y esta pantalla la ignora. Abrir un hilo no lleva a ningún sitio.
  void onOpenThread;

  // `search` es el valor del input; `query` es el término activo que se envía al
  // servidor. La spec §3 filtra al pulsar Enter, no en cada tecla.
  const [search, setSearch] = useState('');
  const [query, setQuery] = useState('');
  const [page, setPage] = useState(1);
  const [data, setData] = useState<ThreadPage | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    let cancelled = false;
    setLoading(true);
    setError(null);
    fetchThreadPage({ orgId: profile.orgId, search: query, page })
      .then((res) => {
        if (cancelled) return;
        setData(res);
        setLoading(false);
      })
      .catch((e: unknown) => {
        if (cancelled) return;
        setError(formatError(e));
        setLoading(false);
      });
    return () => {
      cancelled = true;
    };
  }, [profile.orgId, query, page]);

  const total = data?.total ?? 0;
  const pages = pageCount(total, PAGE_SIZE);

  return (
    <div className={styles.page}>
      <p className={styles.eyebrow}>Módulo 04 · Mensajería E2EE</p>
      <h1 className={styles.title}>Hilos</h1>
      <p className={styles.subtitle}>
        Tus conversaciones con otros distribuidores. Todo el contenido está cifrado
        de extremo a extremo.
      </p>

      <div className={styles.e2eeBar}>
        <i className={`ti ti-lock ${styles.e2eeIcon}`} aria-hidden="true" />
        E2EE activo · frase de seguridad en sesión · contenido descifrado localmente
      </div>

      <div className={styles.actionsBar}>
        <div className={styles.searchWrap}>
          <i className={`ti ti-search ${styles.searchIcon}`} aria-hidden="true" />
          <input
            type="text"
            className={styles.searchInput}
            placeholder="Buscar por nombre de organización..."
            aria-label="Buscar por nombre de organización"
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            onKeyDown={(e) => {
              if (e.key === 'Enter') {
                setQuery(search.trim());
                setPage(1);
              }
            }}
          />
        </div>
        <div className={styles.contactGroup}>
          {/* DIR-01 no está entre las 8 pantallas del MVP: se pinta deshabilitado
              con el motivo visible, como el botón de subida de INV-01 (F-023 e). */}
          <button type="button" className={styles.primaryBtn} disabled>
            <i className={`ti ti-address-book ${styles.btnIcon}`} aria-hidden="true" />
            Nuevo contacto
          </button>
          <span className={styles.outOfScope} data-testid="directorio-scope">
            El Directorio queda fuera del MVP
          </span>
        </div>
        <span className={styles.threadCount} data-testid="pag-info">
          {total.toLocaleString('es-ES')} hilos · Página {page.toLocaleString('es-ES')} de{' '}
          {pages.toLocaleString('es-ES')}
        </span>
      </div>

      {error ? (
        <div className={styles.errorBanner} role="alert">
          <i className={`ti ti-alert-triangle ${styles.errorIcon}`} aria-hidden="true" />
          <span>No se pudieron cargar los hilos. {error}</span>
        </div>
      ) : null}

      {loading && !data ? (
        <div className={styles.statusBox}>Cargando hilos…</div>
      ) : null}

      {data ? <ThreadList threads={data.threads} now={now} onOpen={() => {}} /> : null}

      {data && data.total > 0 ? (
        <div className={styles.pagination}>
          <button
            type="button"
            className={styles.pageBtn}
            disabled={page <= 1}
            aria-label="Página anterior"
            onClick={() => setPage((p) => Math.max(1, p - 1))}
          >
            ‹
          </button>
          {Array.from({ length: pages }, (_, i) => i + 1).map((n) => (
            <button
              key={n}
              type="button"
              className={`${styles.pageBtn} ${n === page ? styles.pageActive : ''}`}
              aria-current={n === page ? 'page' : undefined}
              onClick={() => setPage(n)}
            >
              {n.toLocaleString('es-ES')}
            </button>
          ))}
          <button
            type="button"
            className={styles.pageBtn}
            disabled={page >= pages}
            aria-label="Página siguiente"
            onClick={() => setPage((p) => Math.min(pages, p + 1))}
          >
            ›
          </button>
        </div>
      ) : null}
    </div>
  );
}

