import { previewLabel, relativeTime, stateTone, type ThreadSummary } from '../../lib/threads';
import styles from './ThreadList.module.css';

/**
 * MSG-01 · Lista de Hilos — componente presentacional.
 *
 * Pinta las filas en el orden en que llegan: el orden es del servidor, nunca se
 * reordena aquí. Al pulsar una fila avisa con el id del hilo, no con el objeto.
 * No carga datos ni pagina.
 *
 * La fila es un <li> con un <button> dentro. El <li> conserva su rol `listitem`
 * a propósito: un role explícito lo sustituiría, y el contrato consulta ese rol
 * (F-131).
 */
export interface ThreadListProps {
  threads: ThreadSummary[];
  /** Inyectable para que los tests no dependan del reloj. */
  now?: Date | undefined;
  onOpen: (id: string) => void;
}

export function ThreadList({ threads, now = new Date(), onOpen }: ThreadListProps) {
  if (threads.length === 0) {
    return (
      <div className={styles.empty}>
        <p className={styles.emptyText}>
          Todavía no tienes ninguna conversación. Usa el Directorio para contactar
          con otras organizaciones.
        </p>
        <button type="button" className={styles.emptyBtn} disabled>
          Ir al Directorio
        </button>
        {/* El Directorio (DIR-01) no está entre las 8 pantallas del MVP: el botón
            no lleva a ningún sitio y el motivo se enseña visible (F-128). */}
        <p className={styles.emptyHint}>El Directorio queda fuera del MVP.</p>
      </div>
    );
  }

  return (
    <ul className={styles.list}>
      {threads.map((thread) => (
        <li key={thread.id} className={styles.row}>
          <button
            type="button"
            className={styles.rowBtn}
            onClick={() => onOpen(thread.id)}
          >
            <span className={styles.rowTop}>
              <span className={styles.orgName}>{thread.counterpartyName}</span>
              <span className={styles.countryBadge}>{thread.counterpartyCountry}</span>
            </span>
            <span className={styles.rowMeta}>
              <time className={styles.threadTs} dateTime={thread.lastItemAt}>
                {relativeTime(thread.lastItemAt, now)}
              </time>
            </span>
            <span className={styles.rowBottom}>
              {/* Metadatos únicamente: tipo de elemento y referencia, nunca
                  contenido descifrado (spec §7, F-027). */}
              <span className={styles.preview}>{previewLabel(thread.lastItem)}</span>
              <span className={`${styles.stateBadge} ${styles[stateTone(thread.state)]}`}>
                {thread.state}
              </span>
            </span>
          </button>
        </li>
      ))}
    </ul>
  );
}
